<script setup>
import {ref,onMounted,computed,reactive} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,messageOf} from '../api';import {auth} from '../auth';import {freshnessLabel,isConfirmationStale,formatShanghai} from '../time'
const route=useRoute(),router=useRouter(),item=ref(null),slots=ref([]),interest=ref(null),interestList=ref([]),comments=ref([]),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),selected=ref(null),comment=ref(''),replyingId=ref(null),replyText=ref('');const pickup=reactive({location:'',startAt:'',endAt:''});
const mine=computed(()=>auth.user&&item.value&&auth.user.id===item.value.publisher.id),canWant=computed(()=>auth.user&&!mine.value&&item.value?.status==='AVAILABLE'),statusText=computed(()=>({AVAILABLE:'可领取',RESERVED:'待交接',COMPLETED:'已送出'}[item.value?.status]||''));
const topComments=computed(()=>comments.value.filter(c=>c.parentId==null).map(c=>({...c,replies:comments.value.filter(r=>r.parentId===c.id)})));
async function load(){loading.value=true;error.value='';try{const [a,b,c]=await Promise.all([api.get(`/items/detail/${route.params.id}`),api.get(`/items/${route.params.id}/slots`),api.get(`/items/${route.params.id}/comments`)]);item.value=a.data;slots.value=b.data;comments.value=c.data;pickup.location=item.value.pickupLocation||'';if(auth.user){if(mine.value)interestList.value=(await api.get(`/items/${route.params.id}/interests`)).data;else interest.value=(await api.get(`/items/${route.params.id}/interests/mine`)).data}}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
async function act(fn,msg){busy.value=true;error.value='';notice.value='';try{await fn();notice.value=msg;await load()}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
const want=()=>{if(!auth.user)return router.push('/login');return act(()=>api.post(`/items/${item.value.id}/interests`,{slotId:selected.value}),'已提交意向，等待发布者确认。')};const cancelInterest=()=>act(()=>api.delete(`/items/${item.value.id}/interests/mine`),'意向已取消。');const confirm=id=>act(()=>api.post(`/interests/${id}/confirm`),'已确认领取人，物品进入待交接。');const confirmAvailable=()=>act(()=>api.post(`/items/${item.value.id}/confirm-available`),'已确认物品仍在。');
const savePickup=()=>act(()=>api.post(`/items/${item.value.id}/pickup-options`,{location:pickup.location,slots:[{startAt:`${pickup.startAt}:00`,endAt:`${pickup.endAt}:00`}]}),'交接信息已保存。');async function sendComment(){if(!auth.user)return router.push('/login');await act(()=>api.post(`/items/${item.value.id}/comments`,{content:comment.value}),'留言已发布。');comment.value=''}
function openReply(id){replyingId.value=replyingId.value===id?null:id;replyText.value='';error.value='';notice.value=''}
async function sendReply(parentId){const text=replyText.value;await act(()=>api.post(`/items/${item.value.id}/comments/${parentId}/replies`,{content:text}),'回复已发布。');replyText.value='';replyingId.value=null}
function price(i){return i.tradeType==='FREE'?'免费送':i.tradeType==='NEGOTIABLE'?'随便给':`¥${Number(i.price).toFixed(2)}`}
onMounted(load)
</script>
<template><p v-if="loading" class="state">加载详情中…</p><p v-else-if="error&&!item" class="state error">{{error}} <button @click="load">重试</button></p><div v-else-if="item" class="detail-page"><article class="detail"><img :src="item.imageUrl" alt="物品占位图"><div><div class="meta-row"><span class="pill">{{statusText}}</span><span class="freshness">{{freshnessLabel(item.publishedAt)}}</span></div><p class="eyebrow">{{item.category}} · {{item.publisher.nickname}} 发布</p><h1>{{item.title}}</h1><strong class="price">{{price(item)}}</strong><p class="description">{{item.description}}</p><div class="time-panel"><p>发布于：{{formatShanghai(item.publishedAt)}}</p><p>最近确认：{{formatShanghai(item.lastConfirmedAt)}}</p><p v-if="isConfirmationStale(item.lastConfirmedAt)" class="stale">状态较久未更新，建议先询问</p><p v-if="item.pickupLocation">公共交接地点：{{item.pickupLocation}}</p></div><button v-if="mine&&item.status==='AVAILABLE'" :disabled="busy" @click="confirmAvailable">确认还在</button></div></article>
<section class="panel"><h2>交接时段</h2><p v-if="!slots.length" class="state">暂无有效未来时段。</p><div v-else class="stack"><label v-for="s in slots" :key="s.id" class="choice"><input v-if="canWant" v-model="selected" type="radio" :value="s.id">{{formatShanghai(s.startAt)}} 至 {{formatShanghai(s.endAt)}}</label></div><template v-if="canWant"><p v-if="interest">当前意向：<strong>{{interest.status==='WAITING'?'等待发布者确认':interest.status==='CONFIRMED'?'已确认':'已取消'}}</strong></p><button :disabled="busy||!selected" @click="want">我想要</button> <button v-if="interest?.status==='WAITING'" class="secondary" :disabled="busy" @click="cancelInterest">取消意向</button></template><p v-if="!auth.user&&item.status==='AVAILABLE'"><RouterLink to="/login">登录后选择时段并表达想要</RouterLink></p></section>
<section v-if="mine&&item.status==='AVAILABLE'&&!slots.length" class="panel"><h2>补充交接信息</h2><label>公共地点<input v-model="pickup.location" maxlength="200"></label><div class="form-row"><label>开始<input v-model="pickup.startAt" type="datetime-local"></label><label>结束<input v-model="pickup.endAt" type="datetime-local"></label></div><button :disabled="busy" @click="savePickup">保存地点和时段</button></section>
<section v-if="mine" class="panel"><h2>意向名单</h2><p v-if="!interestList.length" class="state">暂无意向。</p><div v-for="x in interestList" :key="x.id" class="list-row"><div><strong>{{x.nickname}}</strong><p>{{formatShanghai(x.startAt)}} 至 {{formatShanghai(x.endAt)}} · {{x.status}}</p></div><button v-if="x.status==='WAITING'&&item.status==='AVAILABLE'" :disabled="busy" @click="confirm(x.id)">确认此人</button></div></section>
<section class="panel comments-panel"><h2>公开留言</h2><p v-if="!topComments.length" class="state">暂无留言。</p><article v-for="c in topComments" :key="c.id" class="comment-thread"><div class="comment"><strong>{{c.nickname}}</strong><p>{{c.content}}</p><div class="comment-meta"><small>{{formatShanghai(c.createdAt)}}</small><button v-if="mine&&item.status!=='COMPLETED'" type="button" class="text-button" @click="openReply(c.id)">{{replyingId===c.id?'收起':'回复'}}</button></div></div><div v-for="r in c.replies" :key="r.id" class="comment reply"><strong>发布者回复</strong><p>{{r.content}}</p><small>{{formatShanghai(r.createdAt)}}</small></div><form v-if="replyingId===c.id&&mine&&item.status!=='COMPLETED'" class="reply-form" @submit.prevent="sendReply(c.id)"><label>回复内容<textarea v-model="replyText" maxlength="500" required rows="2" placeholder="公开回复这条问题"></textarea></label><div class="reply-actions"><button :disabled="busy">{{busy?'提交中…':'发布回复'}}</button><button type="button" class="secondary" :disabled="busy" @click="openReply(c.id)">取消</button></div></form></article><form v-if="item.status!=='COMPLETED'" class="new-comment-form" @submit.prevent="sendComment"><label>留言<textarea v-model="comment" maxlength="500" required rows="3" placeholder="公开询问物品情况，请勿留下私人联系方式"></textarea></label><button :disabled="busy">{{busy?'提交中…':'发布留言'}}</button></form><p v-else class="state">已送出物品的留言与回复为只读。</p></section><p v-if="notice" class="success">{{notice}}</p><p v-if="error" class="error">{{error}}</p></div></template>